#!/usr/bin/env bash
# Generated by pipeline_compiler. nvinfer_backport must be on the GStreamer
# plugin path (verify: gst-inspect-1.0 nvinfer_backport). Override CAM /
# CAM_W / CAM_H / CAM_FPS / CAM_FMT via env to match your camera's
# supported capture modes (`v4l2-ctl --list-formats-ext -d <device>`).
set -euo pipefail
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

CAM="${CAM:-/dev/video0}"
CAM_W=${CAM_W:-1920}
CAM_H=${CAM_H:-1080}
CAM_FPS=${CAM_FPS:-30}
CAM_FMT="${CAM_FMT:-YUYV}"

# ── H.264 encoder selection (run time, not build time) ────────────────
# NVENC needs /dev/v4l2-nvenc, which dGPU workstations lack even though the
# nvv4l2h264enc ELEMENT is installed — so probe the device node, not the
# element. FORCE_SW_ENC=1 forces x264enc; BITRATE is in kbit/s for both.
BITRATE=${BITRATE:-8000}
if [ -e /dev/v4l2-nvenc ] && gst-inspect-1.0 nvv4l2h264enc >/dev/null 2>&1 \
   && [ -z "${FORCE_SW_ENC:-}" ]; then
  # Hardware: NVMM in, bitrate in bits/s.
  H264ENC="nvvideoconvert ! video/x-raw(memory:NVMM),format=NV12 ! nvv4l2h264enc idrinterval=30 bitrate=$(( BITRATE * 1000 ))"
  echo "[run.sh] encoder: nvv4l2h264enc (NVENC) @ ${BITRATE}kbit/s" >&2
else
  # Software: needs SYSTEM memory, so nvvideoconvert pulls it off NVMM first;
  # bitrate is already kbit/s. key-int-max matches the hardware idrinterval so
  # a client can join an rtsp stream mid-way either way.
  H264ENC="nvvideoconvert ! video/x-raw,format=I420 ! videoconvert ! x264enc speed-preset=veryfast tune=zerolatency bitrate=${BITRATE} key-int-max=30"
  echo "[run.sh] encoder: x264enc (software) @ ${BITRATE}kbit/s — no /dev/v4l2-nvenc" >&2
fi

# ── Metadata sink config ──────────────────────────────────────────
# Read by the nvcustomprocess user libraries in build/ (the element
# has no config-file property). Override any of these at run time:
#   MQTT_HOST=10.0.0.9 ./run.sh      JSON_OUT=/tmp/d.json ./run.sh
# MQTT needs a reachable broker. None running? Start the one that
# ships with DeepStream:  /usr/local/sbin/mosquitto -p ${MQTT_PORT} &
# A missing broker never fails the pipeline — the video still runs
# and the library reports that it published nothing.
export MQTT_HOST="${MQTT_HOST:-localhost}"
export MQTT_PORT="${MQTT_PORT:-1883}"
export MQTT_TOPIC="${MQTT_TOPIC:-pipegen/detection/vtest-h264}"
export MQTT_QOS="${MQTT_QOS:-0}"
export MQTT_CLIENT_ID="${MQTT_CLIENT_ID:-pipegen-detection-vtest-h264-$$}"
export MQTT_KEEPALIVE="${MQTT_KEEPALIVE:-60}"
export MQTT_INTERVAL="${MQTT_INTERVAL:-1}"
export MQTT_SKIP_EMPTY="${MQTT_SKIP_EMPTY:-0}"
export MQTT_PAYLOAD="${MQTT_PAYLOAD:-frame}"
export MQTT_MIN_CONF="${MQTT_MIN_CONF:-0.0}"
export MQTT_STATUS="${MQTT_STATUS:-0.5}"
export JSON_MASK_OUTLINE="${JSON_MASK_OUTLINE:-0}"
cat >&2 <<MQTTHELP

  ── Publishing detections over MQTT ──────────────────────────
  Broker : ${MQTT_HOST}:${MQTT_PORT}
  Topic  : ${MQTT_TOPIC}

  To CHECK messages are arriving — start it BEFORE the pipeline,
  because messages sent while nobody is listening are discarded,
  not queued.

  From this machine (nothing to install):
      docker run --rm --network host --entrypoint mosquitto_sub craftifaidocker/deepstream:7.1-${DS_ARCH:-amd64}-v3 -h ${MQTT_HOST} -p ${MQTT_PORT} -t '${MQTT_TOPIC}' -v

  From any machine that has the mosquitto clients installed:
      mosquitto_sub -h ${MQTT_HOST} -p ${MQTT_PORT} -t '${MQTT_TOPIC}' -v

  To USE it, subscribe to that topic from your own program. One
  JSON message per frame: frame number, camera id, timestamp, and
  a list of objects — each with a label, a tracking id that
  follows it between frames, a confidence and a bounding box.

  Change the broker without rebuilding:
      MQTT_HOST=10.0.0.9 ./run.sh
  ─────────────────────────────────────────────────────────────

MQTTHELP

if [ -f "${DIR}/parsers/Makefile" ] && command -v make >/dev/null 2>&1; then
  make -C "${DIR}/parsers" || { echo "parser/.so build failed" >&2; exit 1; }
fi

timeout --signal=INT --kill-after=2s 5s gst-launch-1.0 -e \
  nvstreammux name=mux batch-size=1 width=768 height=576 batched-push-timeout=40000 live-source=0 \
  nvurisrcbin uri="file:///home/dhyey/videos/vtest_h264.mp4" ! mux.sink_0 \
  mux. ! queue max-size-buffers=4 \
  ! nvvideoconvert ! queue max-size-buffers=4 \
  ! nvinfer_backport config-file-path="${DIR}/configs/config_det_pgie.txt" \
  ! queue max-size-buffers=4 \
  ! nvtracker tracker-width=640 tracker-height=384 \
      ll-lib-file=/opt/nvidia/deepstream/deepstream/lib/libnvds_nvmultiobjecttracker.so \
      ll-config-file="${DIR}/configs/config_tracker.yml" \
      display-tracking-id=1 \
  ! queue max-size-buffers=4 \
  ! nvcustomprocess custom-lib-path="${DIR}/build/libprivacy_render_process.so" \
      process-func-name=NvDsCustomPostProcess \
  ! queue max-size-buffers=4 \
  ! nvcustomprocess custom-lib-path="${DIR}/build/libmqtt_publish.so" \
      process-func-name=MqttPublish \
  ! queue max-size-buffers=4 \
  ! nvdsosd \
  ! queue max-size-buffers=4 \
  ! nvvideoconvert \
  ! ${H264ENC} \
  ! h264parse config-interval=1 \
  ! rtspclientsink location="rtsp://localhost:8554/argonyx" protocols=tcp latency=0
